write: {"content": "import csv

def bubble_sort_by_name(rows):
    n = len(rows)
    for i in range(n):
        swapped = False
        for j in range(0, n - i - 1):
            if rows[j]['компонент'].lower() > rows[j+1]['компонент'].lower():
                rows[j], rows[j+1] = rows[j+1], rows[j]
                swapped = True
        if not swapped:
            break
    return rows

def main():
    with open('компоненты.csv', newline='', encoding='utf-8') as f:
        reader = csv.DictReader(f, delimiter=';')
        rows = list(reader)

    sorted_rows = bubble_sort_by_name(rows)

    print('компонент;лицензия;страна правообладателя')
    for r in sorted_rows:
        print(f"{r['компонент']};{r['лицензия']};{r['страна правообладателя']}")

if __name__ == '__main__':
    main()
